import type { LessonContent } from '../schema';
import type { SloScenario } from '@/lib/devops/slo';

/**
 * KUB14 SLI、SLO 與 SLA. A devops-explorer lesson (D6 SLOs, the monitoring-dashboard activity, no terminal). A made-up
 * city library's online borrowing service, loan-api, running on the course's Kubernetes cluster (示意資料, not any real
 * library, monitoring product or provider). Three SLO scenarios generated by the seeded series generator of
 * src/lib/devops/series.ts: this month in hourly buckets (a bad deployment rolled back after two hours, a slow error
 * leak of five days), one day in 5-minute buckets (the first day of a 30-day window, windowTotal stated: a one-bucket blip
 * during a node drain and a 20-minute configuration incident), and last month in hourly buckets (a nine-hour database
 * outage that breaks the SLA). Every exercise answer is computed from these scenarios by src/lib/devops (slo.ts, burn.ts,
 * slo-check.ts; devopsContentProblems checks them); none is written here. The numbers quoted in the prose were computed
 * by the same engine.
 */

/**
 * This month, 720 hourly buckets (the 30-day window), 20,000 requests an hour (no noise: 14,400,000 in all), 99.9%.
 * Bad: 6 ± 3 an hour; +1,200 an hour in hours 150–151 (a new version, rolled back); +25 an hour in hours 400–519 (a slow
 * leak). Budget ⌊14,400,000 × 10 ÷ 10,000⌋ = 14,400. Consumed 933 before hour 150, 2,409 in hours 150–151 (3,342 after
 * hour 151: 23.2%, remaining 76.8%), 9,797 at the end (68.0%, remaining 4,603); SLI 99.932% (met), SLA credit 0.
 * Burn at hour 151 over 1 h: 1,203 ÷ 20,000 ÷ 0.1% = 60.2, hours left 11,058 ÷ 1,203 = 9.2; at hour 500 over 24 h:
 * 742 ÷ 480,000 ÷ 0.1% = 1.5, hours left 207.7.
 * - fast (1 h / 1 h ≥ 14.4): fires hours 150–151, misses the leak. slow (3 d / 6 h ≥ 1): fires 150–156, then 439–521:
 *   the leak is detected after 39 h = 2,340 minutes.
 */
const month = (): SloScenario => ({
  service: 'loan-api（市立圖書館線上借閱）', sli: '回應碼不是 5xx、而且在 500 ms 內完成的借閱 API 請求',
  bucketMinutes: 60, buckets: 720,
  total: { shape: { seed: 1401, baseline: 20000 } },
  bad: { shape: { seed: 1402, baseline: 6, noise: 3, changes: [
    { kind: 'spike', at: 150, minutes: 2, delta: 1200 },
    { kind: 'spike', at: 400, minutes: 120, delta: 25 }] } },
  objective: { targetPermyriad: 9990, windowMinutes: 43200 },
  sla: { targetPermyriad: 9950, credits: [{ belowPermyriad: 9950, creditPercent: 10 }, { belowPermyriad: 9900, creditPercent: 25 }, { belowPermyriad: 9500, creditPercent: 50 }] },
  incidents: [
    { id: 'bad-release', label: '新版本的借閱 API 回傳 500', start: 150, end: 152 },
    { id: 'slow-leak', label: '快取設定錯誤造成的零星逾時', start: 400, end: 520 },
  ],
  alerts: [
    { id: 'fast', label: '快速消耗：1 小時的消耗率 ≥ 14.4（呼叫值班）', longMinutes: 60, shortMinutes: 60, factorTenths: 144, severity: 'critical' },
    { id: 'slow', label: '緩慢消耗：3 天與 6 小時的消耗率 ≥ 1（開成待辦）', longMinutes: 4320, shortMinutes: 360, factorTenths: 10, severity: 'warning' },
  ],
});

/**
 * One day, 288 buckets of 5 minutes, the first day of a 30-day window: windowTotal 12,960,000 (about 432,000 a day for
 * 30 days), budget 12,960. Requests 1,500 ± 150 per bucket (434,189 in the day); bad 1 ± 1, +40 in bucket 40 (03:20, a
 * node drain, no incident), +200 in buckets 150–153 (12:30–12:50, a configuration change). Consumed 1,143 (8.8%); the
 * day's SLI is 99.737% (below 99.9%) while 91.2% of the month's budget is left.
 * Burn at bucket 40: 5 min 27.3, 1 h 3.0. Bucket 150: 5 min 132.4, 1 h 11.5; bucket 151: 1 h 22.5; bucket 153: 6 h 7.9.
 * - page (1 h / 5 min ≥ 14.4): fires at minute 755 (12:35, delay 5), resolves at 770 (12:50). 5 / 5 ≥ 14.4 also fires
 *   at 200 (a false alert); 60 / 60 ≥ 14.4 resolves only at 820; 60 / 5 ≥ 50 and 360 / 30 ≥ 14.4 miss the incident.
 */
const day = (): SloScenario => ({
  service: 'loan-api（市立圖書館線上借閱）', sli: '回應碼不是 5xx、而且在 500 ms 內完成的借閱 API 請求',
  bucketMinutes: 5, buckets: 288,
  total: { shape: { seed: 1403, baseline: 1500, noise: 150 } },
  bad: { shape: { seed: 1404, baseline: 1, noise: 1, changes: [
    { kind: 'spike', at: 40, minutes: 1, delta: 40 },
    { kind: 'spike', at: 150, minutes: 4, delta: 200 }] } },
  objective: { targetPermyriad: 9990, windowMinutes: 43200, windowTotal: 12_960_000 },
  incidents: [{ id: 'bad-config', label: '連線池設定改錯，部分請求逾時', start: 150, end: 154 }],
  alerts: [{ id: 'page', label: '快速消耗：1 小時與 5 分鐘的消耗率 ≥ 14.4（呼叫值班）', longMinutes: 60, shortMinutes: 5, factorTenths: 144, severity: 'critical' }],
});

/**
 * Last month, 720 hourly buckets, 20,000 requests an hour, 99.9%; bad 6 ± 3 an hour, +12,000 an hour in hours 610–618
 * (the database primary fails and the failover does not complete for nine hours). Budget 14,400; consumed 3,663 before
 * hour 610, used up at hour 610 (minute 36,600); 112,264 at the end. SLI 99.220%: below the SLA's 99.5%, not below
 * 99% → credit 10%. Counting the nine hours as fully down (711 ÷ 720 = 98.75%) would wrongly give 25%.
 */
const outage = (): SloScenario => ({
  service: 'loan-api（市立圖書館線上借閱）', sli: '回應碼不是 5xx、而且在 500 ms 內完成的借閱 API 請求',
  bucketMinutes: 60, buckets: 720,
  total: { shape: { seed: 1405, baseline: 20000 } },
  bad: { shape: { seed: 1406, baseline: 6, noise: 3, changes: [{ kind: 'spike', at: 610, minutes: 9, delta: 12000 }] } },
  objective: { targetPermyriad: 9990, windowMinutes: 43200 },
  sla: { targetPermyriad: 9950, credits: [{ belowPermyriad: 9950, creditPercent: 10 }, { belowPermyriad: 9900, creditPercent: 25 }, { belowPermyriad: 9500, creditPercent: 50 }] },
  incidents: [{ id: 'db-failover', label: '資料庫主節點故障，切換卡住九小時', start: 610, end: 619 }],
  alerts: [{ id: 'fast', label: '快速消耗：1 小時的消耗率 ≥ 14.4（呼叫值班）', longMinutes: 60, shortMinutes: 60, factorTenths: 144, severity: 'critical' }],
});

